const fs = require('fs-extra');
const path = require('path');

const outputFileName = "LuaInterfaces.lua"


var generatedList = {}

function getAlias(config, key) {
    for (var filePath in config) {
        var item = config[filePath]
        if (item.Alias == key) {
            return item.Key
        }
    }
}

function buildContent(config) {
    var content = ""
    for (var rbxPath in config) {
        var item = config[rbxPath]
        if (item.UseDirectContent) {
            content += `-- from ${item.FilePath}\n`
            content += `local script = ${rbxPath}\n`
            content += `${item.DirectContent}\n`
            content += `--\n\n`
        } else {

            if (generatedList[item.Key]) {
                var existPath = path.resolve(generatedList[item.Key].FilePath);
                var fullPath = path.resolve(item.FilePath);
                throw new Error(`检测到同名接口: ${item.Key}, \n${existPath}, \n${fullPath}\n\n`)
            }
            generatedList[item.Key] = item

            var isAlias = item.Alias != null
            var exportOrAlias = `${isAlias ? "" : "export"}`
            if (item.HasClassCtor) {
                content += `local ctor = require(${rbxPath})\n`
                content += `${exportOrAlias} type ${item.Key} = typeof(ctor.new())`
            }
            else if (item.HasTypeDefine) {
                content += `local source = require(${rbxPath})\n`
                content += `${exportOrAlias} type ${item.Key} = source.Type`
            } else if (item.HasNameDefine) {
                content += `local source = require(${rbxPath})\n`
                content += `${exportOrAlias} type ${item.Key} = source.${item.Key}`
            } else {
                content += `${exportOrAlias} type ${item.Key} = typeof(require(${rbxPath}))`
            }

            var alias = getAlias(config, item.Key)
            if (alias) {
                content += `&${alias}\n`
            } else {
                content += "\n"
            }
            content += "\n"
        }

    }
    generatedList = {}
    return content
}

function tryMakeServiceCollectionExtensions(outputPath) {
    fs.ensureDirSync(outputPath);
    var filePath = path.join(outputPath, "ServiceCollectionExtensions.d.lua")
    if (fs.existsSync(filePath)) {
        return
    }
    var content = `
-- 声明扩展接口
export type IServiceCollection_extensions = typeof(require(
	game.ReplicatedStorage._robloxManifest.Extensions.IServiceCollection_extensions
))
    `

    fs.writeFileSync(filePath, content);

}

function gen(config, outputPath) {
    fs.ensureDirSync(outputPath);
    var content = buildContent(config)
    fs.writeFileSync(path.join(outputPath, outputFileName), content);
    tryMakeServiceCollectionExtensions(outputPath)
    console.log(`write file ${path.join(outputPath, outputFileName)}`)
}


module.exports = gen;